// Обратная функция: формирование буфера из JSON по схеме полей
// Используйте ту же схему `fields`, что и для парсинга.
// Поддерживаемые типы:
//   - uint8, uint16le, uint16be, uint32le, uint32be
//   - int8, int16le, int16be, int32le, int32be
//   - string (требует `length` и опционально `encoding`, по умолчанию 'ascii')
//   - bytes (ожидает Buffer или массив чисел 0-255, требует `length`)
//   - skip (пропускает байты, заполняет нулями, не требует значения в JSON)

// ===== НАСТРОЙКА СХЕМЫ =====
// Заполните массив в соответствии с форматом ваших данных
var fields = [
    // Примеры (раскомментируйте и измените под свою задачу):
    // { name: 'header',  offset: 0, type: 'uint8' },
    // { name: 'length',  offset: 1, type: 'uint16le' },
    // { name: 'data',    offset: 3, type: 'bytes', length: 10 },
    // { name: 'message', offset: 13, type: 'string', length: 20, encoding: 'utf8' },
    // { name: 'checksum',offset: 33, type: 'uint16be' }
    { name: 'start', offset: 0, type: 'uint16le' },
    { name: 'obj', offset: 2, type: 'uint16le' },
    { name: 'cmd', offset: 4, type: 'uint16le' },
    { name: 'len', offset: 10, type: 'uint16le' },
    { name: 'val', offset: 12, type: 'uint16le' }
];

// ===== КОД ФУНКЦИИ (не изменять без необходимости) =====
// Проверка входных данных
if (!msg.payload || typeof msg.payload !== 'object' || Array.isArray(msg.payload)) {
    node.error("Входной payload должен быть объектом JSON", msg);
    return null;
}

var json = msg.payload;

// Вычисляем необходимый размер буфера
var maxEnd = 0;
for (var i = 0; i < fields.length; i++) {
    var f = fields[i];
    var size;
    if (f.type === 'uint8' || f.type === 'int8') size = 1;
    else if (f.type === 'uint16le' || f.type === 'uint16be' || f.type === 'int16le' || f.type === 'int16be') size = 2;
    else if (f.type === 'uint32le' || f.type === 'uint32be' || f.type === 'int32le' || f.type === 'int32be') size = 4;
    else if (f.type === 'string' || f.type === 'bytes' || f.type === 'skip') {
        if (f.length === undefined) throw new Error("Поле '" + (f.name || 'skip') + "' требует length");
        size = f.length;
    } else throw new Error("Неподдерживаемый тип: " + f.type);

    var end = f.offset + size;
    if (end > maxEnd) maxEnd = end;
}

// Создаём буфер, заполненный нулями
var buffer = Buffer.alloc(maxEnd, 0);

try {
    for (var i = 0; i < fields.length; i++) {
        var f = fields[i];
        var offset = f.offset;
        var type = f.type;
        var name = f.name;
        var length = f.length;

        if (type === 'skip') continue; // ничего не записываем, байты уже нулевые

        // Проверяем наличие поля в JSON
        if (!json.hasOwnProperty(name)) {
            throw new Error("Отсутствует обязательное поле '" + name + "' в JSON");
        }
        var value = json[name];

        // Запись в зависимости от типа
        if (type === 'uint8') {
            if (typeof value !== 'number' || !Number.isInteger(value) || value < 0 || value > 255)
                throw new Error("Поле '" + name + "' должно быть целым числом от 0 до 255");
            buffer.writeUInt8(value, offset);
        }
        else if (type === 'uint16le') {
            if (typeof value !== 'number' || !Number.isInteger(value) || value < 0 || value > 65535)
                throw new Error("Поле '" + name + "' должно быть целым числом от 0 до 65535");
            buffer.writeUInt16LE(value, offset);
        }
        else if (type === 'uint16be') {
            if (typeof value !== 'number' || !Number.isInteger(value) || value < 0 || value > 65535)
                throw new Error("Поле '" + name + "' должно быть целым числом от 0 до 65535");
            buffer.writeUInt16BE(value, offset);
        }
        else if (type === 'uint32le') {
            if (typeof value !== 'number' || !Number.isInteger(value) || value < 0 || value > 4294967295)
                throw new Error("Поле '" + name + "' должно быть целым числом от 0 до 4294967295");
            buffer.writeUInt32LE(value, offset);
        }
        else if (type === 'uint32be') {
            if (typeof value !== 'number' || !Number.isInteger(value) || value < 0 || value > 4294967295)
                throw new Error("Поле '" + name + "' должно быть целым числом от 0 до 4294967295");
            buffer.writeUInt32BE(value, offset);
        }
        else if (type === 'int8') {
            if (typeof value !== 'number' || !Number.isInteger(value) || value < -128 || value > 127)
                throw new Error("Поле '" + name + "' должно быть целым числом от -128 до 127");
            buffer.writeInt8(value, offset);
        }
        else if (type === 'int16le') {
            if (typeof value !== 'number' || !Number.isInteger(value) || value < -32768 || value > 32767)
                throw new Error("Поле '" + name + "' должно быть целым числом от -32768 до 32767");
            buffer.writeInt16LE(value, offset);
        }
        else if (type === 'int16be') {
            if (typeof value !== 'number' || !Number.isInteger(value) || value < -32768 || value > 32767)
                throw new Error("Поле '" + name + "' должно быть целым числом от -32768 до 32767");
            buffer.writeInt16BE(value, offset);
        }
        else if (type === 'int32le') {
            if (typeof value !== 'number' || !Number.isInteger(value) || value < -2147483648 || value > 2147483647)
                throw new Error("Поле '" + name + "' должно быть целым числом от -2147483648 до 2147483647");
            buffer.writeInt32LE(value, offset);
        }
        else if (type === 'int32be') {
            if (typeof value !== 'number' || !Number.isInteger(value) || value < -2147483648 || value > 2147483647)
                throw new Error("Поле '" + name + "' должно быть целым числом от -2147483648 до 2147483647");
            buffer.writeInt32BE(value, offset);
        }
        else if (type === 'string') {
            if (typeof value !== 'string')
                throw new Error("Поле '" + name + "' должно быть строкой");
            var encoding = f.encoding || 'ascii';
            var byteLen = Buffer.byteLength(value, encoding);
            if (byteLen > length)
                throw new Error("Строка поля '" + name + "' слишком длинная (макс. " + length + " байт в кодировке " + encoding + ")");
            buffer.write(value, offset, length, encoding);
        }
        else if (type === 'bytes') {
            // Принимаем Buffer или массив чисел
            if (!Buffer.isBuffer(value)) {
                if (Array.isArray(value) && value.every(v => typeof v === 'number' && v >= 0 && v <= 255 && Number.isInteger(v))) {
                    value = Buffer.from(value);
                } else {
                    throw new Error("Поле '" + name + "' должно быть Buffer или массивом байт (0-255)");
                }
            }
            if (value.length !== length)
                throw new Error("Длина поля '" + name + "' должна быть ровно " + length + " байт");
            value.copy(buffer, offset, 0, length);
        }
        else {
            throw new Error("Внутренняя ошибка: неподдерживаемый тип " + type);
        }
    }
} catch (err) {
    //node.error("Ошибка формирования буфера: " + err.message, msg);
    return null;
}

// Возвращаем буфер
msg.payload = buffer;
return msg;

// Пользовательская функция для разбора бинарного буфера в JSON
// Основана на настраиваемой схеме полей (массив `fields`)
// Поддерживаемые типы:
//   - uint8, uint16le, uint16be, uint32le, uint32be
//   - int8, int16le, int16be, int32le, int32be
//   - string (требует `length` и опционально `encoding`, по умолчанию 'ascii')
//   - bytes (возвращает Buffer, требует `length`)
//   - skip (пропускает байты, не создаёт поля)

// ===== НАСТРОЙКА СХЕМЫ =====
var fields = [
    // Примеры (раскомментируйте и измените под свою задачу):
    // { name: 'header',  offset: 0, type: 'uint8' },
    // { name: 'length',  offset: 1, type: 'uint16le' },
    // { name: 'data',    offset: 3, type: 'bytes', length: 10 },
    // { name: 'message', offset: 13, type: 'string', length: 20, encoding: 'utf8' },
    // { name: 'checksum',offset: 33, type: 'uint16be' }
    { name: 'cmd', offset: 2, type: 'uint16le' },
    { name: 'to', offset: 4, type: 'uint16le' },
    { name: 'len', offset: 8, type: 'uint16le' }
];

if (!Buffer.isBuffer(msg.payload)) {
    node.error("Входной payload не является Buffer", msg);
    return null;
}

var buffer = msg.payload;
var result = {};

try {
    for (var i = 0; i < fields.length; i++) {
        var field = fields[i];
        var offset = field.offset;
        var type = field.type;
        var name = field.name;
        var length = field.length; // для string, bytes, skip

        // Определяем размер поля в байтах для проверки границ
        var size;
        if (type === 'uint8' || type === 'int8') {
            size = 1;
        } else if (type === 'uint16le' || type === 'uint16be' || type === 'int16le' || type === 'int16be') {
            size = 2;
        } else if (type === 'uint32le' || type === 'uint32be' || type === 'int32le' || type === 'int32be') {
            size = 4;
        } else if (type === 'string' || type === 'bytes' || type === 'skip') {
            if (length === undefined) {
                throw new Error("Поле '" + (name || 'skip') + "' требует указания length");
            }
            size = length;
        } else {
            throw new Error("Неподдерживаемый тип: " + type);
        }

        // Проверяем, что буфер содержит достаточно данных
        if (offset + size > buffer.length) {
            throw new Error("Буфер слишком короткий для поля '" + (name || 'skip') + "' по смещению " + offset + " (требуется " + size + " байт)");
        }

        // Чтение значения
        var value;
        if (type === 'uint8') {
            value = buffer.readUInt8(offset);
        } else if (type === 'uint16le') {
            value = buffer.readUInt16LE(offset);
        } else if (type === 'uint16be') {
            value = buffer.readUInt16BE(offset);
        } else if (type === 'uint32le') {
            value = buffer.readUInt32LE(offset);
        } else if (type === 'uint32be') {
            value = buffer.readUInt32BE(offset);
        } else if (type === 'int8') {
            value = buffer.readInt8(offset);
        } else if (type === 'int16le') {
            value = buffer.readInt16LE(offset);
        } else if (type === 'int16be') {
            value = buffer.readInt16BE(offset);
        } else if (type === 'int32le') {
            value = buffer.readInt32LE(offset);
        } else if (type === 'int32be') {
            value = buffer.readInt32BE(offset);
        } else if (type === 'string') {
            var encoding = field.encoding || 'ascii';
            value = buffer.toString(encoding, offset, offset + length);
        } else if (type === 'bytes') {
            value = buffer.slice(offset, offset + length);
        } else if (type === 'skip') {
            continue; // ничего не сохраняем
        }

        // Для всех полей, кроме skip, добавляем значение в результат
        // @ts-ignore
        if (type !== 'skip') {
            if (!name) {
                throw new Error("Поле с индексом " + i + " не имеет имени (и это не skip)");
            }
            result[name] = value;
        }
    }
} catch (err) {
    //node.error("Ошибка разбора: " + err.message, msg);
    return null;
}

// Заменяем payload на полученный объект и передаём дальше
msg.payload = result;
msg.original = buffer;
return msg;
